<script setup>import AdminShell from '../../components/AdminShell.vue';import AppIcon from '../../components/AppIcon.vue';import StatusPill from '../../components/StatusPill.vue';import {orders,vehicles,alerts,stats} from '../../api/mock';const lane=[{name:'上海 → 杭州',count:7,rate:96,width:86},{name:'上海 → 苏州',count:6,rate:100,width:74},{name:'上海 → 宁波',count:5,rate:91,width:62},{name:'上海 → 无锡',count:4,rate:94,width:50}];</script>
<template><AdminShell><template #title>运营总览</template><div class="welcome-row"><div><h2>下午好，林泽宇</h2><p>今日共有 28 张运输订单，1 项异常需要关注。</p></div><button class="primary-btn">＋ 新建运输订单</button></div><div class="stat-grid"><article v-for="s in stats" :key="s[0]" :class="s[3]"><div class="stat-icon"><AppIcon :name="s[0].includes('车辆')?'truck':s[0].includes('异常')?'bell':'order'"/></div><div><span>{{s[0]}}</span><strong>{{s[1]}}</strong><small>{{s[2]}}</small></div></article></div><div class="dashboard-grid"><section class="panel map-panel"><div class="panel-head"><div><h3>在途车辆动态</h3><p>华东区域 · 实时位置</p></div><span class="live"><i></i>实时更新</span></div><div class="map-stage"><div class="map-water w1"></div><div class="map-water w2"></div><div class="road r1"></div><div class="road r2"></div><div class="road r3"></div><div class="city sh"><b>上海</b><small>运营中心</small></div><div class="city hz"><b>杭州</b><small>7 辆</small></div><div class="city sz"><b>苏州</b><small>6 辆</small></div><div class="city nb"><b>宁波</b><small>5 辆</small></div><div class="truck-dot d1">16</div><div class="truck-dot d2">7</div><div class="truck-dot danger">!</div><div class="map-legend"><span><i class="green-dot"></i>运行正常 15</span><span><i class="red-dot"></i>运输异常 1</span></div></div></section><section class="panel alerts-panel"><div class="panel-head"><div><h3>运营预警</h3><p>按紧急程度排序</p></div><a>全部预警</a></div><div class="alert-item" v-for="a in alerts" :key="a.title"><span :class="a.level">{{a.level}}</span><div><b>{{a.title}}</b><p>{{a.detail}}</p><small>{{a.time}}</small></div></div></section><section class="panel route-panel"><div class="panel-head"><div><h3>核心线路表现</h3><p>今日运输量与准点率</p></div><a>线路分析</a></div><div class="lane" v-for="l in lane" :key="l.name"><div><b>{{l.name}}</b><span>{{l.count}} 单</span></div><div class="bar"><i :style="{width:l.width+'%'}"></i></div><strong>{{l.rate}}%</strong></div></section><section class="panel fleet-panel"><div class="panel-head"><div><h3>车辆状态</h3><p>自营与签约运力</p></div><a>车辆监控</a></div><div class="fleet-row" v-for="v in vehicles.slice(0,3)" :key="v.plate"><div class="vehicle-icon"><AppIcon name="truck"/></div><div><b>{{v.plate}}</b><small>{{v.type}} · {{v.driver}}</small></div><StatusPill :status="v.status"/></div></section></div><section class="panel order-preview"><div class="panel-head"><div><h3>今日重点运输</h3><p>优先展示加急、异常与即将超时订单</p></div><RouterLink to="/admin/orders">查看全部订单 →</RouterLink></div><table><thead><tr><th>运输单号</th><th>客户 / 货物</th><th>运输线路</th><th>车辆司机</th><th>计划送达</th><th>状态</th></tr></thead><tbody><tr v-for="o in orders.slice(0,4)" :key="o.id"><td><b>{{o.no}}</b><small>{{o.priority}}</small></td><td>{{o.customer}}<small>{{o.cargo}}</small></td><td><span class="route-cell">{{o.origin}} <i>→</i> {{o.destination}}</span></td><td>{{o.plate}}<small>{{o.driver}}</small></td><td>{{o.delivery}}<small>{{o.eta}}</small></td><td><StatusPill :status="o.status"/></td></tr></tbody></table></section></AdminShell></template>
